require __DIR__.'/inc/v11.php';v11_admin();v11_require();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verify();try{$pdo=db();$tables=$pdo->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);$name='eksioglu-db-'.date('Ymd-His').'.sql';header('Content-Type: application/sql; charset=utf-8');header('Content-Disposition: attachment; filename="'.$name.'"');header('Cache-Control: no-store');echo "-- EKŞİOĞLU MySQL backup\nSET FOREIGN_KEY_CHECKS=0;\n";foreach($tables as $t){$qt='`'.str_replace('`','``',$t).'`';$create=$pdo->query('SHOW CREATE TABLE '.$qt)->fetch(PDO::FETCH_NUM);echo "DROP TABLE IF EXISTS $qt;\n".$create[1].";\n";$rows=$pdo->query('SELECT * FROM '.$qt);while($r=$rows->fetch(PDO::FETCH_ASSOC)){$cols=array_map(fn($x)=>'`'.str_replace('`','``',$x).'`',array_keys($r));$vals=array_map(fn($x)=>$x===null?'NULL':$pdo->quote((string)$x),array_values($r));echo 'INSERT INTO '.$qt.' ('.implode(',',$cols).') VALUES ('.implode(',',$vals).");\n";}}echo "SET FOREIGN_KEY_CHECKS=1;\n";exit;}catch(Throwable $e){$err=$e->getMessage();}}require __DIR__.'/inc/layout.php';top('Güvenlik ve Yedek');?><link rel="stylesheet" href="assets/v11.css?v=331301"><div class="v11-head"><h1>Güvenlik & Veritabanı Yedeği</h1><p>Yalnızca yönetici erişimi. Yedek, tarayıcıya SQL dosyası olarak indirilir.</p></div><?php if($err):?><p class="error"><?=h($err)?></p><?php endif;?><div class="v11-card"><h2>Veritabanı Yedeğini İndir</h2><p>Bu dosya müşteri bilgileri içerir. Güvenli ve şifreli bir ortamda saklayın. Dosya yedekleri ve otomatik zamanlama bu işlemde dahil değildir.</p><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><button>SQL Yedeği İndir</button></form></div><?php bottom();
